from __future__ import annotations

import hashlib
import math
import threading
import time
from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import EVENT_TYPES, Node, Subscription, Workflow, _finite_json, _identifier
from .notifier import Notifier
from .store import Store


def _json_type(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return "other"


def _evaluate_condition(node: Node, input_data: Any) -> bool:
    current = input_data
    for segment in node.path.split("."):
        if not isinstance(current, dict) or segment not in current:
            return False
        current = current[segment]
    return _json_type(current) == _json_type(node.equals) and current == node.equals


def _new_iteration() -> dict[str, Any]:
    return {"completed_nodes": [], "skipped_nodes": [], "condition_results": {}, "outputs": {}, "attempts": {}}


def _new_loop_state() -> dict[str, Any]:
    return {"status": "pending", "current_iteration": 0, "iterations": [], "end_reason": None}


DEFAULT_LEASE_SECONDS = 30.0


class ChronicleFlow:
    def __init__(self, database: str, notifier: Notifier | None = None):
        self.store = Store(database)
        self.notifier = notifier or Notifier()
        # Deliveries are collected only while a mutating idempotent operation
        # runs, so queries, replay, and recovery never trigger a delivery.
        self._delivery_local = threading.local()

    def _idempotent(
        self, key: str | None, operation: str, action: Callable[[], dict[str, Any]], deliver: bool = True
    ) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        with self.store.transaction() as connection:
            existing = connection.execute("SELECT operation, response FROM idempotency WHERE key = ?", (key,)).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            # Recovery is a read-like operation: it never triggers deliveries,
            # even if a due timeout takes effect while it runs.
            self._delivery_local.queue = [] if deliver else None
            try:
                response = action()
            except BaseException:
                # Rolled-back state appends no events, so nothing is delivered.
                self._delivery_local.queue = None
                raise
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, self.store.encode(response)),
            )
        # The state transition is durable first; only then do webhooks go out,
        # and delivery failures never alter the operation's concluded result.
        if deliver:
            self._flush_deliveries()
        self._delivery_local.queue = None
        return response

    def create_workflow(self, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or not {"id", "nodes"} <= set(raw) <= {"id", "nodes", "subscriptions"}:
            raise ValidationError("workflow must contain id and nodes, plus optional subscriptions")
        subscriptions_raw = raw.get("subscriptions", [])
        if not isinstance(subscriptions_raw, list):
            raise ValidationError("subscriptions must be an array")
        subscriptions = tuple(Subscription.parse(item) for item in subscriptions_raw)
        document = {"id": raw["id"], "nodes": raw["nodes"]}
        workflow = Workflow.parse(document)
        result = workflow.as_dict()
        if subscriptions:
            result["subscriptions"] = [subscription.as_dict() for subscription in subscriptions]

        def create() -> dict[str, Any]:
            try:
                self.store.connection.execute(
                    "INSERT INTO workflows(id, document) VALUES (?, ?)",
                    (workflow.id, self.store.encode(workflow.as_dict())),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"workflow {workflow.id} already exists") from error
                raise
            for subscription in subscriptions:
                self.store.connection.execute(
                    "INSERT INTO subscriptions(scope_type, workflow_id, execution_id, url, events, timeout_seconds, max_attempts) "
                    "VALUES ('workflow', ?, NULL, ?, ?, ?, ?)",
                    (
                        workflow.id,
                        subscription.url,
                        self.store.encode(list(subscription.events)),
                        subscription.timeout_seconds,
                        subscription.max_attempts,
                    ),
                )

                "reason": payload.get("reason"),
            }
            if "loop_id" in payload:
                record["loop_id"] = payload["loop_id"]
                record["iteration"] = payload["iteration"]
            rebuilt["waiting_approval"] = None
            rebuilt["approvals"].append(record)
        elif event_type == "execution_completed" and rebuilt is not None:
            rebuilt["status"] = "completed"
        elif event_type == "execution_terminated" and rebuilt is not None:
            rebuilt["status"] = "terminated"
            rebuilt["termination_reason"] = payload["reason"]
            if "waiting_approval" in rebuilt:
                rebuilt["waiting_approval"] = None
            if payload["reason"] in ("retries_exhausted", "rejected") and "node_id" in payload:
                rebuilt["failed_nodes"].append(payload["node_id"])
    if rebuilt is None:
        raise ConflictError("execution event stream has no start event")
    return {"consistent": rebuilt == stored, "execution": rebuilt}

def _append(self, execution_id: str, event_type: str, payload: dict[str, Any]) -> int:
    row = self.store.connection.execute(
        "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM events WHERE execution_id = ?",
        (execution_id,),
    ).fetchone()
    sequence = row["sequence"]
    self.store.connection.execute(
        "INSERT INTO events(execution_id, sequence, type, payload, occurred_at) VALUES (?, ?, ?, ?, ?)",
        (execution_id, sequence, event_type, self.store.encode(payload), self.store.now()),
    )
    self._schedule_deliveries(execution_id, sequence, event_type, payload)
    return sequence

def _schedule_deliveries(
    self, execution_id: str, sequence: int, event_type: str, payload: dict[str, Any]
) -> None:
    """Queue webhooks for subscriptions watching this event.

    Runs inside the mutating operation's transaction. Queries, replay, and
    recovery have no active queue, so their event appends (a timeout taking
    effect during a read, for example) never schedule a delivery.
    """
    queue = getattr(self._delivery_local, "queue", None)
    if queue is None:
        return
    if event_type not in EVENT_TYPES:
        return
    rows = self.store.connection.execute(
        "SELECT id, url, events, timeout_seconds, max_attempts FROM subscriptions "
        "WHERE (scope_type = 'execution' AND execution_id = ?) "
        "OR (scope_type = 'workflow' AND execution_id IS NULL AND workflow_id = "
        "(SELECT workflow_id FROM executions WHERE id = ?)) ORDER BY id",
        (execution_id, execution_id),
    ).fetchall()
    subscriptions = [
        {
            "id": row["id"],
            "url": row["url"],
            "events": tuple(self.store.decode(row["events"])),
            "timeout_seconds": row["timeout_seconds"],
            "max_attempts": row["max_attempts"],
        }
        for row in rows
        if event_type in self.store.decode(row["events"])
    ]
    if subscriptions:
        queue.append(
            {
                "execution_id": execution_id,
                "sequence": sequence,
                "event_type": event_type,
                "payload": payload,
                "subscriptions": subscriptions,
            }
        )

@staticmethod
def _webhook_message(execution_id: str, event_type: str, payload: dict[str, Any]) -> dict[str, Any]:
    # Fixed key order: the event kind and execution identifier first, then
    # the node or approver the event relates to.
    message: dict[str, Any] = {"event_type": event_type, "execution_id": execution_id}
    if "node_id" in payload:
        message["node_id"] = payload["node_id"]
    if event_type == "approval_decided":
        message["approver"] = payload["approver"]
        message["decision"] = payload["decision"]
    return message

@staticmethod
def _delivery_key(execution_id: str, sequence: int, subscription_id: int) -> str:
    # Deterministic per (event, subscription): retries of the same event
    # reuse the key, distinct events and targets get distinct keys.
    digest = hashlib.sha256(f"{execution_id}|{sequence}|{subscription_id}".encode("utf-8")).hexdigest()
    return f"wfdlv-{digest[:32]}"

def _flush_deliveries(self) -> None:
    """Deliver every queued webhook after commit and persist the history.

    Network attempts happen outside any database transaction. All outcomes
    are recorded, but none can change the already-concluded operation
    result.
    """
    queue = getattr(self._delivery_local, "queue", None) or []
    records: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any]]] = []
    for item in queue:
        message = self._webhook_message(item["execution_id"], item["event_type"], item["payload"])
        for subscription in item["subscriptions"]:
            key = self._delivery_key(item["execution_id"], item["sequence"], subscription["id"])
            result = self.notifier.deliver(
                subscription["url"],
                message,
                key,
                subscription["timeout_seconds"],
                subscription["max_attempts"],
            )
            records.append((item, subscription, result))
    if not records:
        return
    with self.store.transaction() as connection:
        for item, subscription, result in records:
            connection.execute(
                "INSERT INTO deliveries(execution_id, event_sequence, subscription_id, idempotency_key, "
                "target, event_type, attempts, status, attempt_details, created_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    item["execution_id"],
                    item["sequence"],
                    subscription["id"],
                    result["idempotency_key"],
                    subscription["url"],
                    item["event_type"],
                    result["attempts"],
                    result["status"],
                    self.store.encode(result["attempt_log"]),
                    self.store.now(),
                ),
            )

def deliveries(self, execution_id: str) -> dict[str, Any]:
    exists = self.store.connection.execute(
        "SELECT 1 FROM executions WHERE id = ?", (execution_id,)
    ).fetchone()
    if not exists:
        raise NotFoundError(f"execution {execution_id} was not found")
    rows = self.store.connection.execute(
        "SELECT target, event_type, attempts, status, idempotency_key, attempt_details, event_sequence "
        "FROM deliveries WHERE execution_id = ? ORDER BY event_sequence, subscription_id",
        (execution_id,),
    ).fetchall()
    delivery_records: list[dict[str, Any]] = []
    for row in rows:
        attempt_log = []
        for attempt in self.store.decode(row["attempt_details"]):
            entry: dict[str, Any] = {"attempt": attempt["attempt"]}
            if "status_code" in attempt:
                entry["status_code"] = attempt["status_code"]
            else:
                entry["error"] = attempt["error"]
            attempt_log.append(entry)
        # Fixed key order keeps the history output stable.
        delivery_records.append(
            {
                "target": row["target"],
                "event_type": row["event_type"],
                "attempts": row["attempts"],
                "status": row["status"],
                "idempotency_key": row["idempotency_key"],
                "attempt_log": attempt_log,
            }
        )
    return {"deliveries": delivery_records}

