import json
import tempfile
import threading
import unittest
import urllib.error
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from chronicleflow.errors import NotFoundError, ValidationError
from chronicleflow.notifier import Notifier
from chronicleflow.service import ChronicleFlow


class RoutingTransport:
    """Scripted notifier transport: per-URL queues of status codes or errors."""

    def __init__(self):
        self.scripts = {}
        self.requests = []

    def set_outcomes(self, url, outcomes):
        self.scripts[url] = list(outcomes)

    def __call__(self, url, body, headers, timeout):
        outcomes = self.scripts[url]
        index = min(len([r for r in self.requests if r[0] == url]), len(outcomes) - 1)
        self.requests.append((url, json.loads(body), dict(headers), timeout))
        outcome = outcomes[index]
        if isinstance(outcome, Exception):
            raise outcome
        return outcome


class WebhookServiceTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.transport = RoutingTransport()
        self.notifier = Notifier(transport=self.transport, sleep=lambda seconds: None)
        self.service = ChronicleFlow(str(Path(self.directory.name) / "test.db"), notifier=self.notifier)
        self.workflow = {
            "id": "orders",
            "nodes": [
                {"id": "reserve", "kind": "task", "depends_on": []},
                {"id": "charge", "kind": "task", "depends_on": ["reserve"]},
            ],
        }

    def tearDown(self):
        self.directory.cleanup()

    def create(self, workflow=None, subscriptions=None, execution_id="run-1", execution_subscriptions=None):
        workflow_document = dict(workflow or self.workflow)
        if subscriptions is not None:
            workflow_document["subscriptions"] = subscriptions
        self.service.create_workflow(workflow_document, "w1")
        execution = {"id": execution_id, "workflow_id": workflow_document["id"], "input": {"order": 7}}
        if execution_subscriptions is not None:
            execution["subscriptions"] = execution_subscriptions
        self.service.create_execution(execution, "e1")

    def test_workflow_subscription_receives_node_and_completion_events(self):
        self.transport.set_outcomes("http://hook.invalid/a", [200, 200, 200])
        self.create(
            subscriptions=[
                {"url": "http://hook.invalid/a", "events": ["node_completed", "execution_completed"]}
            ]
        )
        self.service.advance("run-1", {"output": {"id": 1}}, "a1")
        self.service.advance("run-1", {"output": {"id": 2}}, "a2")
        messages = [request[1] for request in self.transport.requests]
        self.assertEqual(
            [
                {"event_type": "node_completed", "execution_id": "run-1", "node_id": "reserve"},
                {"event_type": "node_completed", "execution_id": "run-1", "node_id": "charge"},
                {"event_type": "execution_completed", "execution_id": "run-1"},
            ],
            messages,
        )

    def test_message_has_stable_key_order(self):
        self.transport.set_outcomes("http://hook.invalid/a", [200])
        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[{"url": "http://hook.invalid/a", "events": ["node_completed"]}],
        )
        self.service.advance("run-1", {"output": {}}, "a1")
        _, _, headers, timeout = self.transport.requests[0]
        self.assertEqual("application/json; charset=utf-8", headers["Content-Type"])
        self.assertIn("Idempotency-Key", headers)
        self.assertTrue(headers["Idempotency-Key"].startswith("wfdlv-"))
        self.assertEqual(5.0, timeout)

    def test_event_filtering_delivers_only_subscribed_types(self):
        self.transport.set_outcomes("http://hook.invalid/ends", [200])
        self.create(
            subscriptions=[{"url": "http://hook.invalid/ends", "events": ["execution_completed"]}]
        )
        self.service.advance("run-1", {"output": {}}, "a1")
        self.service.advance("run-1", {"output": {}}, "a2")
        self.assertEqual(1, len(self.transport.requests))
        self.assertEqual("execution_completed", self.transport.requests[0][1]["event_type"])

    def test_failure_then_retry_success_is_recorded(self):
        self.transport.set_outcomes(
            "http://hook.invalid/flaky",
            [503, urllib.error.URLError("boom"), 200],
        )
        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[
                {"url": "http://hook.invalid/flaky", "events": ["node_completed"], "max_attempts": 3}
            ],
        )
        state = self.service.advance("run-1", {"output": {}}, "a1")
        self.assertEqual("completed", state["status"])
        history = self.service.deliveries("run-1")["deliveries"]
        self.assertEqual(1, len(history))
        record = history[0]
        self.assertEqual("delivered", record["status"])
        self.assertEqual(3, record["attempts"])
        self.assertEqual(
            [
                {"attempt": 1, "status_code": 503},
                {"attempt": 2, "error": "<urlopen error boom>"},
                {"attempt": 3, "status_code": 200},
            ],
            record["attempt_log"],
        )

    def test_all_attempts_failing_records_failed_but_operation_concludes(self):
        self.transport.set_outcomes("http://hook.invalid/down", [500, 502])
        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[
                {"url": "http://hook.invalid/down", "events": ["node_completed"], "max_attempts": 2}
            ],
        )
        state = self.service.advance("run-1", {"output": {"v": 1}}, "a1")
        self.assertEqual("completed", state["status"])
        self.assertEqual(["only"], state["completed_nodes"])
        record = self.service.deliveries("run-1")["deliveries"][0]
        self.assertEqual("failed", record["status"])
        self.assertEqual(2, record["attempts"])
        self.assertEqual([{"attempt": 1, "status_code": 500}, {"attempt": 2, "status_code": 502}], record["attempt_log"])

    def test_idempotency_key_is_reused_across_retries_and_unique_per_event(self):
        self.transport.set_outcomes("http://hook.invalid/a", [500, 200, 200])
        self.transport.set_outcomes("http://hook.invalid/b", [200])
        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[
                {"url": "http://hook.invalid/a", "events": ["node_completed", "execution_completed"], "max_attempts": 2},
                {"url": "http://hook.invalid/b", "events": ["node_completed"]},
            ],
        )
        self.service.advance("run-1", {"output": {}}, "a1")
        node_requests = [r for r in self.transport.requests if r[1]["event_type"] == "node_completed"]
        # Target a: two attempts (500 then 200) carry the same key; target b has its own.
        keys_a = {r[2]["Idempotency-Key"] for r in node_requests if r[0] == "http://hook.invalid/a"}
        keys_b = {r[2]["Idempotency-Key"] for r in node_requests if r[0] == "http://hook.invalid/b"}
        self.assertEqual(1, len(keys_a))
        self.assertEqual(1, len(keys_b))
        self.assertNotEqual(keys_a, keys_b)
        completion_key = {
            r[2]["Idempotency-Key"] for r in self.transport.requests if r[1]["event_type"] == "execution_completed"
        }
        self.assertEqual(1, len(completion_key - keys_a))

    def test_history_is_stable_in_event_order_with_multiple_targets(self):
        self.transport.set_outcomes("http://hook.invalid/a", [200, 200])
        self.transport.set_outcomes("http://hook.invalid/b", [200, 200])
        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[
                {"url": "http://hook.invalid/a", "events": ["node_completed", "execution_completed"]},
                {"url": "http://hook.invalid/b", "events": ["node_completed", "execution_completed"]},
            ],
        )
        self.service.advance("run-1", {"output": {}}, "a1")
        records = self.service.deliveries("run-1")["deliveries"]
        self.assertEqual(
            [
                ("node_completed", "http://hook.invalid/a"),
                ("node_completed", "http://hook.invalid/b"),
                ("execution_completed", "http://hook.invalid/a"),
