        self.create(
            workflow={"id": "orders", "nodes": [{"id": "only", "kind": "task", "depends_on": []}]},
            subscriptions=[
                {"url": "http://hook.invalid/a", "events": ["node_completed", "execution_completed"], "max_attempts": 2},
                {"url": "http://hook.invalid/b", "events": ["node_completed"]},
            ],
        )
        self.service.advance("run-1", {"output": {}}, "a1")
        node_requests = [r for r in self.transport.requests if r[1]["event_type"] == "node_completed"]
        # Target a: two attempts (500 then 200) carry the same key; target b has its own.
        keys_a = {r[2]["Idempotency-Key"] for r in node_requests if r[0] == "http://hook.invalid/a"}
        keys_b = {r[2]["Idempotency-Key"] for r in node_requests if r[0] == "http://hook.invalid/b"}
        self.assertEqual(1, len(keys_a))
        self.assertEqual(1, len(keys_b))
        self.assertNotEqual(keys_a, keys_b)
        completion_key = {
            r[2]["Idempotency-Key"] for r in self.transport.requests if r[1]["event_type"] == "execution_completed"
        }
        self.assertEqual(1, len(completion_key - keys_a))

