class WebhookValidationTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.service = ChronicleFlow(str(Path(self.directory.name) / "test.db"))
        self.workflow_nodes = [{"id": "only", "kind": "task", "depends_on": []}]

    def tearDown(self):
        self.directory.cleanup()

    def invalid_bodies(self):
        base = {"url": "http://hook.invalid/a", "events": ["node_completed"]}
        yield {**base, "events": []}
        yield {**base, "events": ["node_completed", "node_completed"]}
        yield {**base, "events": ["mystery_event"]}
        yield {**base, "events": "node_completed"}
        yield {"events": ["node_completed"]}
        yield {**base, "url": ""}
        yield {**base, "url": "ftp://hook.invalid/a"}
        yield {**base, "url": "not a url"}
        yield {**base, "url": 7}
        yield {**base, "timeout_seconds": 0}
        yield {**base, "timeout_seconds": -2}
        yield {**base, "timeout_seconds": "5"}
        yield {**base, "timeout_seconds": True}
        yield {**base, "max_attempts": 0}
        yield {**base, "max_attempts": 11}
        yield {**base, "max_attempts": 1.5}
        yield {**base, "max_attempts": True}
        yield {**base, "extra": 1}
        yield "not-an-object"

    def test_invalid_workflow_subscriptions_are_rejected_without_partial_write(self):
        for index, subscription in enumerate(self.invalid_bodies()):
            with self.subTest(subscription=subscription):
                with self.assertRaises(ValidationError):
                    self.service.create_workflow(
                        {"id": f"wf-bad-{index}", "nodes": self.workflow_nodes, "subscriptions": [subscription]},
                        f"key-{index}",
                    )
        # The rejected workflow id is still free: a valid create with it succeeds.
        self.service.create_workflow(
            {"id": "wf-bad-0", "nodes": self.workflow_nodes, "subscriptions": []}, "retry"
        )

    def test_subscriptions_must_be_an_array(self):
        with self.assertRaises(ValidationError):
            self.service.create_workflow(
                {"id": "wf-shape", "nodes": self.workflow_nodes, "subscriptions": {}}, "k1"
            )

    def test_invalid_execution_subscription_leaves_no_execution(self):
        self.service.create_workflow({"id": "wf", "nodes": self.workflow_nodes}, "w1")
        with self.assertRaises(ValidationError):
            self.service.create_execution(
                {
                    "id": "run-bad",
                    "workflow_id": "wf",
                    "input": {},
                    "subscriptions": [{"url": "http://h", "events": ["node_completed"], "max_attempts": 11}],
                },
                "e1",
            )
        # The rejected execution id is free and produces no delivery records later.
        self.service.create_execution({"id": "run-bad", "workflow_id": "wf", "input": {}}, "e2")
        with self.assertRaises(NotFoundError):
            self.service.deliveries("never-existed")

    def test_non_finite_subscription_timeout_is_rejected(self):
        # Parsed as float NaN/Infinity by the service layer (the HTTP layer also
        # rejects the JSON constants before parsing).
        with self.assertRaises(ValidationError):
            self.service.create_workflow(
                {
                    "id": "wf-nan",
                    "nodes": self.workflow_nodes,
                    "subscriptions": [{"url": "http://h", "events": ["node_completed"], "timeout_seconds": float("nan")}],
                },
                "k1",
            )

    def test_subscription_round_trips_on_create_responses(self):
        stored = self.service.create_workflow(
            {
                "id": "wf-echo",
                "nodes": self.workflow_nodes,
                "subscriptions": [
                    {"url": "http://h", "events": ["node_completed"], "timeout_seconds": 2, "max_attempts": 4}
                ],
            },
            "k1",
        )
        self.assertEqual(
            [{"url": "http://h", "events": ["node_completed"], "timeout_seconds": 2.0, "max_attempts": 4}],
            stored["subscriptions"],
        )
        execution = self.service.create_execution(
            {
                "id": "run-echo",
                "workflow_id": "wf-echo",
                "input": {},
                "subscriptions": [{"url": "http://h2", "events": ["execution_completed"]}],
            },
            "k2",
        )
        # Subscriptions never appear in execution state.
        self.assertNotIn("subscriptions", execution)


class WebhookHttpTests(unittest.TestCase):
    @staticmethod
    def _request(port, method, path, body=None, key=None):
        import http.client

        connection = http.client.HTTPConnection("127.0.0.1", port)
        payload = json.dumps(body) if body is not None else None
        headers = {"Content-Type": "application/json"}
        if key is not None:
            headers["Idempotency-Key"] = key
        connection.request(method, path, payload, headers)
        response = connection.getresponse()
        data = response.read()
        connection.close()
        return response.status, data

    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()

        # A target webhook server whose per-path response scripts are set in each test.
        self.lock = threading.Lock()
        self.received = []
        self.status_scripts = {}

        class TargetHandler(BaseHTTPRequestHandler):
            def log_message(this, format, *args):
                return

            def do_POST(this):
                length = int(this.headers.get("Content-Length", "0"))
                raw = this.rfile.read(length)
                with self.lock:
                    script = self.status_scripts.get(this.path, [200])
                    index = min(
                        len([r for r in self.received if r["path"] == this.path]), len(script) - 1
                    )
                    status_code = script[index]
                    self.received.append(
                        {
                            "path": this.path,
                            "body": json.loads(raw),
                            "idempotency_key": this.headers.get("Idempotency-Key"),
                        }
                    )
                this.send_response(status_code)
                this.end_headers()

        self.target = ThreadingHTTPServer(("127.0.0.1", 0), TargetHandler)
        self.target_port = self.target.server_address[1]
        self.target_thread = threading.Thread(target=self.target.serve_forever, daemon=True)
        self.target_thread.start()

        # The service uses the real urllib transport against this local server.
        from chronicleflow.server import Handler

        self.service = ChronicleFlow(str(Path(self.directory.name) / "http-webhooks.db"))
        Handler.service = self.service
        self.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        self.port = self.server.server_address[1]
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()

    def tearDown(self):
        self.server.shutdown()
        self.server.server_close()
        self.target.shutdown()
        self.target.server_close()
        self.directory.cleanup()

    def call(self, method, path, body=None, key=None):
        return self._request(self.port, method, path, body, key)

    @property
    def target_url(self):
        return f"http://127.0.0.1:{self.target_port}"

    def test_real_http_delivery_with_idempotency_header(self):
        status, data = self.call(
            "POST",
            "/workflows",
            {
                "id": "wf-wh",
                "nodes": [{"id": "a", "kind": "task", "depends_on": []}],
                "subscriptions": [{"url": self.target_url + "/hook", "events": ["node_completed"]}],
            },
            "wf-wh",
        )
        self.assertEqual(201, status, data)
        self.call("POST", "/executions", {"id": "run-wh", "workflow_id": "wf-wh", "input": {}}, "ex-wh")
        status, _ = self.call("POST", "/executions/run-wh/advance", {"output": {"v": 1}}, "adv-wh")
        self.assertEqual(200, status)
        self.assertEqual(1, len(self.received))
        request = self.received[0]
        self.assertEqual("/hook", request["path"])
        self.assertEqual({"event_type": "node_completed", "execution_id": "run-wh", "node_id": "a"}, request["body"])
        self.assertTrue(request["idempotency_key"].startswith("wfdlv-"))

    def test_http_retry_after_503_uses_same_key_and_history_shows_both(self):
        self.status_scripts["/flaky"] = [503, 200]
        self.call(
            "POST",
            "/workflows",
            {
                "id": "wf-flaky",
                "nodes": [{"id": "a", "kind": "task", "depends_on": []}],
                "subscriptions": [
                    {"url": self.target_url + "/flaky", "events": ["node_completed"], "max_attempts": 3}
                ],
            },
            "wf-flaky",
        )
        self.call("POST", "/executions", {"id": "run-flaky", "workflow_id": "wf-flaky", "input": {}}, "ex-flaky")
        status, _ = self.call("POST", "/executions/run-flaky/advance", {"output": {}}, "adv-flaky")
        self.assertEqual(200, status)
        self.assertEqual(2, len(self.received))
        self.assertEqual(self.received[0]["idempotency_key"], self.received[1]["idempotency_key"])
        status, data = self.call("GET", "/executions/run-flaky/deliveries")
        self.assertEqual(200, status)
        self.assertTrue(data.endswith(b"\n"))
        self.assertFalse(data.endswith(b"\n\n"))
        record = json.loads(data)["deliveries"][0]
        self.assertEqual("delivered", record["status"])
        self.assertEqual(
            [{"attempt": 1, "status_code": 503}, {"attempt": 2, "status_code": 200}], record["attempt_log"]
        )

    def test_unreachable_target_fails_but_history_is_queryable(self):
        self.call(
            "POST",
            "/workflows",
            {
                "id": "wf-down",
                "nodes": [{"id": "a", "kind": "task", "depends_on": []}],
                "subscriptions": [
                    {"url": "http://127.0.0.1:9/hook", "events": ["node_completed"], "max_attempts": 1, "timeout_seconds": 1}
                ],
            },
            "wf-down",
        )
        self.call("POST", "/executions", {"id": "run-down", "workflow_id": "wf-down", "input": {}}, "ex-down")
        status, data = self.call("POST", "/executions/run-down/advance", {"output": {}}, "adv-down")
        self.assertEqual(200, status)
        self.assertEqual("completed", json.loads(data)["status"])
        status, data = self.call("GET", "/executions/run-down/deliveries")
        self.assertEqual(200, status)
        record = json.loads(data)["deliveries"][0]
        self.assertEqual("failed", record["status"])
        self.assertEqual(1, record["attempts"])
        self.assertIn("error", record["attempt_log"][0])

    def test_deliveries_endpoint_errors(self):
        status, data = self.call("GET", "/executions/ghost/deliveries")
        self.assertEqual(404, status)
        self.assertEqual("not_found", json.loads(data)["error"]["code"])

    def test_invalid_subscription_over_http_is_validation_error(self):
        for index, subscription in enumerate(
            (
                {"url": "http://h", "events": []},
                {"url": "http://h", "events": ["nope"]},
                {"url": "http://h", "events": ["node_completed", "node_completed"]},
                {"url": "", "events": ["node_completed"]},
                {"url": "ftp://h", "events": ["node_completed"]},
                {"url": "http://h", "events": ["node_completed"], "max_attempts": 11},
