class Subscription:
    url: str
    events: tuple[str, ...]
    timeout_seconds: float
    max_attempts: int

    @classmethod
    def parse(cls, raw: Any) -> "Subscription":
        if not isinstance(raw, dict):
            raise ValidationError("each subscription must be an object")
        if not {"url", "events"} <= set(raw) <= {"url", "events", "timeout_seconds", "max_attempts"}:
            raise ValidationError("subscription must contain url and events, plus optional timeout_seconds and max_attempts")
        url = raw["url"]
        if not isinstance(url, str) or not url:
            raise ValidationError("subscription url must be a non-empty http or https URL")
        parts = urlsplit(url)
        if parts.scheme not in ("http", "https") or not parts.netloc:
            raise ValidationError("subscription url must be an http or https URL")
        events = raw["events"]
        if not isinstance(events, list) or not events:
            raise ValidationError("subscription events must be a non-empty array")
        if any(not isinstance(item, str) for item in events):
            raise ValidationError("subscription events must be strings")
        if any(item not in EVENT_TYPES for item in events):
            raise ValidationError(f"subscription events must be one of {', '.join(EVENT_TYPES)}")
        if len(events) != len(set(events)):
            raise ValidationError("subscription events must not contain duplicates")
        timeout_seconds = raw.get("timeout_seconds", DEFAULT_TIMEOUT_SECONDS)
        if isinstance(timeout_seconds, bool) or not isinstance(timeout_seconds, (int, float)):
            raise ValidationError("subscription timeout_seconds must be a positive number of seconds")
        if not math.isfinite(timeout_seconds) or timeout_seconds <= 0:
            raise ValidationError("subscription timeout_seconds must be a positive number of seconds")
        max_attempts = raw.get("max_attempts", DEFAULT_MAX_ATTEMPTS)
        if isinstance(max_attempts, bool) or not isinstance(max_attempts, int):
            raise ValidationError("subscription max_attempts must be a positive integer")
        if not 1 <= max_attempts <= MAX_DELIVERY_ATTEMPTS:
            raise ValidationError(f"subscription max_attempts must be between 1 and {MAX_DELIVERY_ATTEMPTS}")
        return cls(url, tuple(events), float(timeout_seconds), max_attempts)

    def as_dict(self) -> dict[str, Any]:
        return {
            "url": self.url,
            "events": list(self.events),
            "timeout_seconds": self.timeout_seconds,
            "max_attempts": self.max_attempts,
        }


